  return "/functions/v1/lead-magnet-runtime/action";
}

export async function buildLeadMagnetActionUrl(
  enrollmentId: string,
  action: LeadMagnetAction,
): Promise<string> {
  const secret = actionSecret();
  if (!secret) throw new Error("Missing action signing secret");

  const expiry = String(Date.now() + ACTION_TTL_MS);
  const canonical = `${enrollmentId}:${action}:${expiry}`;
  const sig = await hmacSha256Hex(secret, canonical);
  const params = new URLSearchParams({
    e: enrollmentId,
    a: action,
    t: expiry,
    s: sig,
  });
  const pagePath = action === "download" ? leadMagnetDownloadPagePath() : leadMagnetActionPagePath();
  return `${publicAppOrigin()}${pagePath}?${params.toString()}`;
}

export async function verifyLeadMagnetActionUrl(
  enrollmentId: string,
  action: LeadMagnetAction,
  expiryRaw: string,
  sigRaw: string,
): Promise<boolean> {
  const secret = actionSecret();
  if (!secret) return false;

  const expiryMs = Number(expiryRaw);
  if (!Number.isFinite(expiryMs) || expiryMs < Date.now()) return false;
  if (action !== "follow_confirm" && action !== "get_framework" && action !== "download") return false;
  if (!enrollmentId.trim()) return false;

  const canonical = `${enrollmentId}:${action}:${expiryRaw}`;
  const expected = await hmacSha256Hex(secret, canonical);
  return expected === sigRaw.trim();
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

export type LeadMagnetEntitlementResult = {
  entitled: boolean;
  reason?: "no_subscription" | "sales_module_disabled" | "addon_inactive" | "grace_expired";
};

/**
 * Resolves Lead Magnet access for an organization (mandiri add-on + grace, or sales CMS module).
 */
export async function resolveLeadMagnetEntitlement(
  admin: SupabaseClient,
  organizationId: string,
): Promise<LeadMagnetEntitlementResult> {
  const { data: orgRow } = await admin
    .from("organizations")
    .select("subscription_self_service_enabled")
    .eq("id", organizationId)
    .maybeSingle();

  const selfService = orgRow?.subscription_self_service_enabled !== false;

  if (!selfService) {
    const { data: modRow } = await admin
      .from("organization_sales_module_access")
      .select("is_enabled")
      .eq("organization_id", organizationId)
      .eq("module_key", "leadMagnet")
      .maybeSingle();

    if (modRow?.is_enabled === true) {
      return { entitled: true };
    }
    return { entitled: false, reason: "sales_module_disabled" };
  }

  const { data: subRow } = await admin
    .from("organization_subscriptions")
    .select("lead_magnet_active, lead_magnet_grace_until")
    .eq("organization_id", organizationId)
    .maybeSingle();

  if (!subRow) {
    return { entitled: false, reason: "no_subscription" };
  }

  if (subRow.lead_magnet_active === true) {
    return { entitled: true };
  }

  const graceUntil = subRow.lead_magnet_grace_until as string | null;
  if (graceUntil && new Date(graceUntil).getTime() > Date.now()) {
    return { entitled: true };
  }

  return { entitled: false, reason: graceUntil ? "grace_expired" : "addon_inactive" };
}

export async function assertLeadMagnetEntitled(
  admin: SupabaseClient,
  organizationId: string,
): Promise<void> {
  const result = await resolveLeadMagnetEntitlement(admin, organizationId);
  if (!result.entitled) {
    const err = new Error("LEAD_MAGNET_NOT_ENTITLED");
    (err as Error & { code?: string; reason?: string }).code = "LEAD_MAGNET_NOT_ENTITLED";
    (err as Error & { reason?: string }).reason = result.reason;
    throw err;
  }
}

import { LEAD_MAGNET_PAYLOAD_PREFIX, parseLeadMagnetPostbackPayload } from "./types.ts";

export type LeadMagnetAction = "follow_confirm" | "get_framework" | "download";

const ACTION_LABELS: Record<LeadMagnetAction, string> = {
  follow_confirm: "Sudah Follow",
  get_framework: "Ambil Materi",
  download: "Unduh",
};

export function humanizeLeadMagnetAction(action: string): string | null {
  if (action === "follow_confirm" || action === "get_framework" || action === "download") {
    return ACTION_LABELS[action];
  }
  return null;
}

export function humanizeLeadMagnetPayload(payload: string): string | null {
  const parsed = parseLeadMagnetPostbackPayload(payload);
  if (!parsed) return null;
  return humanizeLeadMagnetAction(parsed.action);
}

export function resolveLeadMagnetPostbackDisplayBody(args: {
  payload?: string | null;
  title?: string | null;
  fallback?: string;
}): string {
  const title = (args.title ?? "").trim();
  if (title) return title;

  const payload = (args.payload ?? "").trim();
  const fromPayload = payload ? humanizeLeadMagnetPayload(payload) : null;
  if (fromPayload) return fromPayload;

  return args.fallback ?? "Tombol diklik";
}

export function buildLeadMagnetButtonsMetadata(buttonTitles: string[]): Record<string, unknown> {
  return {
    lead_magnet_buttons: {
      buttons: buttonTitles.map((title) => ({ title: title.trim() })).filter((b) => b.title),
    },
  };
}

export function stripLeadMagnetButtonSuffix(text: string): { body: string; buttonTitles: string[] } {
  const match = text.match(/\n\n\[Tombol:\s*(.+)\]\s*$/);
  if (!match) return { body: text, buttonTitles: [] };
  const body = text.slice(0, match.index).trimEnd();
  const buttonTitles = match[1]
    .split(",")
    .map((part) => part.trim())
    .filter(Boolean);
  return { body, buttonTitles };
}
